{#- dacs-font: one font on every server — Liberation Sans (Arial's letter widths) shipped in the app
    (public/fonts), so a print measures and looks the same on local and live (docs/print-formats.md › Font) -#}
{%- set dacs_base = frappe.utils.get_url() -%}
<style>
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-Regular.ttf') format('truetype'); font-weight: normal; font-style: normal; }
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-Bold.ttf') format('truetype'); font-weight: bold; font-style: normal; }
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-Italic.ttf') format('truetype'); font-weight: normal; font-style: italic; }
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-BoldItalic.ttf') format('truetype'); font-weight: bold; font-style: italic; }
body, body * { font-family: Arial !important; }
/* uniform top margin: the PDF page header (letter head, or the format's own company / store header) starts
   10mm from the top of the paper on every format (Frappe's header template pulls a letter head to the edge) */
body[onload] .wrapper > :first-child { margin-top: -7.5mm !important; }
</style>
{% set company = frappe.get_doc("Company", doc.company) %}
{% set customer = frappe.get_doc("Customer", doc.customer) %}

{# PAGINATION / CHUNKING LOGIC #}
{% set base_chunk = 8 %} {# Reduced slightly to accommodate double address height #}
{% set total_items_count = doc.items|length %}
{% set rem = total_items_count % base_chunk %}

{% if total_items_count > base_chunk and rem == 1 %}
    {% set chunk_size = base_chunk - 1 %}
{% else %}
    {% set chunk_size = base_chunk %}
{% endif %}

{% set chunks = (total_items_count // chunk_size) + (1 if total_items_count % chunk_size else 0) %}

<style>
/* PDF page margins (wkhtmltopdf reads them from this rule, frappe.utils.pdf): top and bottom both set — with
   the page-number footer and no bottom margin the top margin is dropped. PDF only, not a margin on the page box.
   Not on builder formats: their letter head / heading is the PDF page header, which a top margin rule squeezes out. */
.print-format { margin-top: 10mm; margin-bottom: 10mm; }
@media print { body .print-format { margin: 0 !important; } }
.print-format > .page-break:last-child { page-break-after: auto; }
/* terms written in the editor carry its "height: 100%" and scroll bars: inside the page box they stretched to the
   page and showed scroll arrows — the text keeps its own height */
.print-format .ql-editor { height: auto !important; overflow: visible !important; padding: 0 !important; }
.print-format .ql-editor p { margin: 0 !important; }
/* letter head: tighter gaps (the Letter Head record is shared); the PDF page header's own 5mm bottom padding
   is the gap under the heading; a format with its own header (no letter head) starts at the header's top */
.print-format .letter-head > div, .print-format .rn-letterhead > div, .print-format .pr-letterhead > div { margin-bottom: 1px !important; }
.print-format .letter-head > div > div[style*="border-bottom"], .print-format .rn-letterhead > div > div[style*="border-bottom"],
.print-format .pr-letterhead > div > div[style*="border-bottom"] { margin-top: 2px !important; }
html body { padding-bottom: 1mm !important; }
.dacs-items-box { -webkit-box-flex: 1; display: -webkit-box; -webkit-box-orient: vertical; }
.dacs-fill-wrap { -webkit-box-flex: 1; height: 0; overflow: hidden; display: block !important; }
.dacs-fill-wrap { border-bottom: 1px solid #000; }
.dacs-fill-wrap .items { margin-top: -1px; }
body, .print-format { margin:0; padding:0; font-family:Arial, sans-serif; font-size:9pt; color: #000; line-height: 1.2; }

.wrapper { 
    width:100%; 
    border:1px solid #000; 
    box-sizing:border-box; 
    position:relative; 
    min-height: 275mm; 
    display: -webkit-box;
    -webkit-box-orient: vertical;
} 

.header { border-bottom:1px solid #000; padding:8px; position:relative; }
.logo img { max-width:140px; max-height:85px; object-fit:contain; }
.company-name { font-weight:bold; font-size:14pt; }
.company-details { font-size:9pt; line-height:1.2; }

.title-bar { text-align:center; border-top:1.5px solid #000; padding-top:6px; margin-top:8px; }
.title-text { font-size:12pt; font-weight: bold; letter-spacing: 1px; }

.info { border-bottom:1px solid #000; display:flex; font-size:8.5pt; }
.info-left, .info-right { width:50%; padding:6px; vertical-align: top; }
.info-left { border-right:1px solid #000; }
.info-label { font-weight:bold; width:100px; display:inline-block; }

.address-sub-header { text-transform: uppercase; font-size: 8pt; font-weight: bold; color: #555; margin-bottom: 2px; }

table.items { width:100%; border-collapse: collapse; table-layout:fixed; }
.items th, .items td { border: 1px solid #000; padding: 3px 4px; word-wrap: break-word; vertical-align: top; }
.items th { background: #f2f2f2; font-weight: bold; text-align: center; font-size: 9pt; }
.items td { font-size: 9pt; height: 18px; }
.items td.text-center { text-align: center; }
.items td.text-right { text-align: right; }
.items td.bold { font-weight: bold; }

.final-content-area { margin-top: auto; border-top: 1px solid #000; }
.taxes-calc { border-bottom:1px solid #000; padding:6px; }
.summary { display:flex; border-bottom:1px solid #000; }
.summary-left { width:55%; padding:6px; border-right:1px solid #000; font-size: 9pt; }
.summary-right { width:45%; padding:6px; }
.summary-right table { width:100%; border-collapse:collapse; }
.value { text-align:right; font-weight:bold; }

.in-words { border-bottom:1px solid #000; padding:4px 8px; font-size:8.5pt; font-weight:bold; font-style: italic; }
.bank-details-line { border-bottom:1px solid #000; padding:4px 8px; font-size:8pt; }

.footer { display: flex; font-size: 7.5pt; min-height: 90px; }
.footer-left { flex: 1; padding: 8px; border-right: 1px solid #000; }
.footer-right { width: 35%; text-align: center; padding: 8px; display: flex; flex-direction: column; justify-content: space-between; }
.sig-line { border-top: 1px solid #000; width: 90%; margin: 0 auto; padding-top: 5px; font-weight: bold; }

.page-info { position: absolute; top: 105px; right: 10px; font-size: 8.5pt; }
.page-break { page-break-before: always; }
</style>

{% for page_num in range(chunks) %}
<div class="wrapper">

  <!-- Header -->
  <div class="header">
    <div style="display:flex; justify-content:space-between; align-items:center;">
        <div class="logo"><img src="/files/Dacs inc Logo.jpeg" alt="Logo"></div>
        <div style="flex-grow:1; padding-left:20px; text-align: left;">
            <div class="company-name">{{ company.name }}</div>
            <div class="company-details">
                Jaya Sai Towers No.40, 1st & 2nd floor, Sajjan Rao Road, Parvathipuram,<br>
                V.V.Puram, BANGALORE - 560004 | <strong>GSTIN:</strong> 29AAIFD5710C1ZQ<br>
                Phone: 080-41234140 | Email: marketing@dacsinc.in
            </div>
        </div>
    </div>
     <div class="title-bar">
        <div class="title-text">SALES DELIVERY CHALLAN</div>
        <span style="font-size: 9pt;">No: <strong>{{ doc.name }}</strong> | Date: <strong>{{ frappe.utils.formatdate(doc.posting_date, "dd-MMM-yyyy") }}</strong></span>
    </div>
    <div class="page-info">Page {{ page_num + 1 }} of {{ chunks }}</div>
  </div>

  <!-- Customer & Shipping Section -->
  <div class="info">
    <div class="info-left">
      <!-- Billing Address -->
      <div class="address-sub-header">Bill To:</div>
      <strong>M/s. {{ doc.customer_name }}</strong>
      <!--<div style="font-size: 8.5pt; margin-bottom: 8px;">{{ doc.address_display or "" }}</div>-->

      <!-- Shipping Address -->
      <div style="border-top: 1px dashed #ccc; padding-top: 5px;">
          <div class="address-sub-header">Delivery At (Shipping Address):</div>
          <div style="font-size: 8.5pt;">
              {{ doc.shipping_address_display or doc.address_display or "Same as Billing" }}
          </div>
      </div>

      <div style="margin-top:8px;"><strong>GSTIN:</strong> {{ customer.gstin or "N/A" }}</div>
    </div>

    <div class="info-right">
      <div style="margin-bottom:2px;"><span class="info-label">Order No / Date</span>: {{ doc.po_no or "-" }} / {{ frappe.utils.formatdate(doc.po_date) or "" }}</div>
      <div style="margin-bottom:2px;"><span class="info-label">Transporter</span>: {{ doc.transporter_name or "-" }}</div>
      <div style="margin-bottom:2px;"><span class="info-label">Vehicle No</span>: {{ doc.vehicle_no or "-" }}</div>
      <div style="margin-bottom:2px;"><span class="info-label">L.R. No / Date</span>: {{ doc.lr_no or "-" }} / {{ frappe.utils.formatdate(doc.lr_date) or "" }}</div>
      <div style="margin-bottom:2px;"><span class="info-label">Boxes/Bundles</span> : {{ doc.custom_total_boxesbundles or "-" }}</div>
    </div>
  </div>

  <!-- Items Table -->
  {#- Price List Rate and Discount print only when a line has a discount (a price below its list price);
    otherwise only Rate (docs/print-formats.md) -#}
{%- set dd = namespace(on=false) -%}
{%- for it in doc.items -%}{%- if (it.discount_amount or 0) | float > 0.005 or ((it.price_list_rate or 0) | float | abs - (it.rate or 0) | float | abs) > 0.005 -%}{%- set dd.on = true -%}{%- endif -%}{%- endfor -%}
{%- set dacs_disc = dd.on -%}
<style>.dacs-nodisc .dacs-d { display: none; }</style>
<div class="dacs-items-box">
  <table class="items{{ '' if dacs_disc else ' dacs-nodisc' }}">
    <colgroup><col style="width: 28px;"><col style="width: 110px;"><col style="width: 160px;"><col style="width: 52px;"><col style="width: 52px;"><col class="dacs-d" style="width: 62px;"><col style="width: 62px;"><col style="width: 62px;"><col style="width: 80px;"></colgroup>
    <thead>
      <tr>
        <th style="width: 28px;">Sl</th>
        <th style="width: 110px;">Item Code</th>
        <th style="width: 160px;">Description</th>
        <th style="width: 52px;">HSN</th>
        <th style="width: 52px;">Qty</th>
        <th class="dacs-d" style="width: 62px;">Price List Rate</th>
        <th style="width: 62px;">Rate</th>
        <th style="width: 62px;">Tax%</th>
        <th style="width: 80px;">Amount</th>
      </tr>
    </thead>
    <tbody>
      {% set start = page_num * chunk_size %}
      {% set end = (page_num + 1) * chunk_size %}
      {% set items_on_page = doc.items[start:end] %}

      {% for item in items_on_page %}
      <tr>
        <td class="text-center">{{ loop.index + start }}</td>
        <td class="bold">{{ item.item_code }}</td>
        <td>{{ item.description or item.item_name }}</td>
        <td class="text-center">{{ item.gst_hsn_code or "" }}</td>
        <td class="text-center">{{ item.qty | float }} <small>{{ item.uom }}</small></td>
        <td class="dacs-d text-right">{{ "{:,.2f}".format((item.price_list_rate or 0) | float) }}</td>
        <td class="text-right">{{ "{:,.2f}".format(item.rate | float) }}</td>
        <td class="text-center">{{ item.item_tax_template or "" }}</td>
        <td class="text-right"><strong>{{ "{:,.2f}".format(item.amount | float) }}</strong></td>
      </tr>
      {% endfor %}

    </tbody>
  </table>
  <div class="dacs-fill-wrap">
<table class="items{{ '' if dacs_disc else ' dacs-nodisc' }}">
<colgroup><col style="width: 28px;"><col style="width: 110px;"><col style="width: 160px;"><col style="width: 52px;"><col style="width: 52px;"><col class="dacs-d" style="width: 62px;"><col style="width: 62px;"><col style="width: 62px;"><col style="width: 80px;"></colgroup>
<tbody>
{%- for i in range(60) %}<tr>{%- for c in range((9) - (0 if dacs_disc else 1)) %}<td>&nbsp;</td>{%- endfor %}</tr>{%- endfor %}
</tbody>
</table>
</div>
  </div>

  {% if page_num + 1 == chunks %}
  <!-- Bottom Content Area -->
  <div class="final-content-area">
    <div class="taxes-calc">
      <div style="font-weight: bold; font-size: 10pt; margin-bottom: 2px;">GST Breakup:</div>
      <div style="font-size: 8.5pt;">{{ doc.other_charges_calculation | safe }}</div>
    </div>

    <div class="summary">
      <div class="summary-left">
        <strong>Total Items:</strong> {{ doc.items|length }} | <strong>Total Quantity:</strong> {{ doc.total_qty | float or 0 }}
      </div>
      <div class="summary-right">
        <table>
          <tr><td>Net Total</td><td class="value">{{ "{:,.2f}".format(doc.net_total | float) }}</td></tr>
          {% for tax in doc.taxes if tax.tax_amount != 0 %}
            <tr><td>{{ tax.account_head.split(' - ')[0] }}</td><td class="value">{{ "{:,.2f}".format(tax.tax_amount | float) }}</td></tr>
          {% endfor %}
          {% if doc.rounding_adjustment %}
            <tr><td>Round Off</td><td class="value">{{ "{:,.2f}".format(doc.rounding_adjustment | float) }}</td></tr>
          {% endif %}
          <tr style="border-top: 1.5px solid #000;">
            <td style="font-weight:bold; font-size:10pt; padding-top:5px;">Grand Total</td>
            <td class="value" style="font-size: 10pt; padding-top:5px;">INR {{ "{:,.2f}".format(doc.rounded_total or doc.grand_total) }}</td>
          </tr>
        </table>
      </div>
    </div>

    <div class="in-words">Amount in Words: <strong>{{ frappe.utils.money_in_words(doc.rounded_total or doc.grand_total) }}</strong></div>

    <div class="bank-details-line">
        {% set bank_parts = [] %}
        {% set company_banks = frappe.get_doc("Company", doc.company).bank_details_for_printing %}
        {% if company_banks %}
            {% for d in company_banks %}
              {% if d.print_label %}{% set _ = bank_parts.append("<strong>" + d.print_label + ":</strong> " + d.print_value) %}{% endif %}
            {% endfor %}
            {{ bank_parts | join(" | ") | safe }}
        {% endif %}
    </div>

    <div class="footer">
        <div class="footer-left">
          <strong>Terms & Conditions:</strong><br>
          <div style="margin-top:3px; font-size: 8.5pt;">
          {{ doc.terms | replace("\n", "<br>") | safe }}
          </div>
        </div>
        <div class="footer-right">
            <div>For <strong>{{ doc.company }}</strong></div>
            <div class="sig-line" style="margin-top: 50px;">Authorised Signatory</div>
        </div>
    </div>
  </div>
  {% endif %}
</div>

{% if not loop.last %}
<div class="page-break"></div>
{% endif %}

{% endfor %}

<style>/* dacs layout: the PDF engine (wkhtmltopdf) has no flexbox, so header, party / order details, totals and
   footer stacked; the same boxes as table cells, header bordered like the Sales Invoice letter head */
.header > div:first-child { display: table !important; width: 100%; border: 1px solid #000; }
.header > div:first-child > div { display: table-cell !important; vertical-align: middle; }
.header .logo { width: 125px; text-align: center; border-right: 1px solid #000; padding: 6px; }
.header .logo img { max-height: 70px; }
.info, .summary, .footer { display: table !important; width: 100%; table-layout: fixed; }
.info-left, .info-right, .summary-left, .summary-right, .footer-left, .footer-right { display: table-cell !important; vertical-align: top; }
</style>
